// Install the untouched production Chrome package and use an actual running
// OpenAI-compatible model server. Valid responses are never generated by this
// driver. A local gateway only verifies auth and injects labelled HTTP failures.
import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { mkdtemp, readFile, writeFile, mkdir, readdir, rm } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { tmpdir } from 'node:os';
import { createHash, randomBytes } from 'node:crypto';
import { chromium } from 'playwright';

const out = resolve(process.env.SERVER_QA_DIR || 'test-results/server-extension');
const extension = resolve('build/chrome');
const upstream = process.env.SERVER_BASE_URL || 'http://127.0.0.1:11434/v1';
const model = process.env.SERVER_MODEL || 'qwen2.5:1.5b';
const summary = { version: '0.1.6', model, upstream, scope: 'Unmodified installed extension; real HTTP/model server; no on-device model or fabricated translations', passed: false, checks: [], errors: [] };
await mkdir(out, { recursive: true });
async function hashes(dir, prefix = '') {
  const found = {};
  for (const entry of await readdir(join(dir, prefix), { withFileTypes: true })) {
    const path = join(prefix, entry.name);
    if (entry.isDirectory()) Object.assign(found, await hashes(dir, path));
    else found[path] = createHash('sha256').update(await readFile(join(dir, path))).digest('hex');
  }
  return found;
}
const before = await hashes(extension);
const record = async (name, evidence = {}) => { summary.checks.push({ name, passed: true, ...evidence }); await writeFile(join(out, 'summary.json'), JSON.stringify(summary, null, 2)); console.log(JSON.stringify({ name, passed: true, ...evidence })); };
let context, profile, fixture, gateway;
const records = []; let requireAuth = false, forcedStatus = null;
const credential = 'qa-' + randomBytes(24).toString('hex');
const clean = value => String(value).split(credential).join('[redacted]');
const sourceHTML = '<!doctype html><html lang="en"><head><meta charset="utf-8"><title translate="no">Actual server translation</title></head><body><main><h1 id="hello">Hello.</h1><p id="thanks">Thank you.</p><p id="inline">Read <a href="/guide">the guide</a> carefully.</p><div id="late"></div></main><input id="draft" value="private draft"><button id="click" translate="no">Check event</button><pre>const untouched = true;</pre><script>window.clicks=0;document.getElementById("click").onclick=()=>window.clicks++;</script></body></html>';
const listen = server => new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
const close = async server => { if (server) { server.closeAllConnections(); await new Promise(r => server.close(r)); } };
const sleep = ms => new Promise(r => setTimeout(r, ms));
async function screenshot(page, name) {
  await page.bringToFront();
  await page.screenshot({ path: join(out, name + '.png'), fullPage: true, timeout: 20000 });
}
try {
  const modelsReply = await fetch(upstream + '/models'); assert.equal(modelsReply.ok, true);
  const models = await modelsReply.json(); assert.ok(models.data.some(m => m.id === model), 'real model must be available');
  summary.serverModels = models.data.map(m => m.id);
  gateway = createServer(async (req, res) => {
    const row = { method: req.method, path: req.url, authorized: !requireAuth || req.headers.authorization === 'Bearer ' + credential, completed: false, abort: false };
    records.push(row);
    if (!row.authorized || forcedStatus) {
      row.status = !row.authorized ? 401 : forcedStatus;
      res.writeHead(row.status, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: { message: 'Deliberate QA HTTP error' } })); row.completed = true; return;
    }
    const controller = new AbortController();
    res.on('close', () => { if (!row.completed) { row.abort = true; controller.abort(); } });
    try {
      const parts = []; for await (const part of req) parts.push(part);
      const body = parts.length ? Buffer.concat(parts).toString('utf8') : undefined;
      if (body) { const parsed = JSON.parse(body); row.model = parsed.model; row.stream = parsed.stream; row.messageCount = parsed.messages?.length; row.credentialsInBody = body.includes(credential); }
      const response = await fetch(upstream + req.url.replace(/^\/v1/, ''), {
        method: req.method, ...(body ? { body } : {}), headers: { 'Content-Type': 'application/json' }, signal: controller.signal
      });
      row.status = response.status;
      res.writeHead(response.status, { 'Content-Type': response.headers.get('content-type') || 'application/json' });
      for await (const part of response.body) res.write(part);
      row.completed = true; res.end();
    } catch (error) { row.abort ||= controller.signal.aborted; if (!res.destroyed) { res.statusCode = 502; res.end(); } }
  });
  await listen(gateway);
  fixture = createServer((_, res) => { res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' }); res.end(sourceHTML); });
  await listen(fixture);
  profile = await mkdtemp(join(tmpdir(), 'autotranslate-server-'));
  context = await chromium.launchPersistentContext(profile, {
    channel: 'chromium', headless: true, viewport: { width: 1120, height: 900 }, locale: 'ko-KR',
    args: ['--disable-gpu', '--disable-extensions-except=' + extension, '--load-extension=' + extension]
  });
  context.on('page', p => p.on('pageerror', error => summary.errors.push(clean(error.message))));
  const worker = context.serviceWorkers()[0] || await context.waitForEvent('serviceworker', { timeout: 20000 });
  const root = 'chrome-extension://' + new URL(worker.url()).hostname;
  summary.browser = context.browser().version();
  summary.extensionId = new URL(worker.url()).hostname;
  let welcome;
  for (let i = 0; i < 100; i++) { welcome = context.pages().find(p => p.url().includes('/welcome.html')); if (welcome) break; await sleep(50); }
  assert.ok(welcome, 'real onInstalled onboarding window must open');
  await welcome.locator('#serverOptions').click();
  let options;
  for (let i = 0; i < 100; i++) { options = context.pages().find(p => p.url().includes('/options.html')); if (options) break; await sleep(100); }
  assert.ok(options, 'server setup opens the actual options UI');
  await options.waitForFunction(() => document.body.dataset.ready === 'true');
  assert.equal(await options.locator('#engine').inputValue(), 'openai');
  assert.equal(await options.locator('#localSection').isVisible(), false);
  await record('fresh-onboarding-can-select-server-without-model');
  const baseUrl = 'http://127.0.0.1:' + gateway.address().port + '/v1';
  await options.locator('#serverBaseUrl').fill(baseUrl);
  await options.locator('#serverTimeoutMs').fill('120000');
  await options.locator('#serverModel').fill(model);
  await options.locator('#sourceLang').selectOption('en');
  await options.locator('#targetLang').selectOption('ko');
  await options.locator('#loadServerModels').click();
  await options.waitForFunction(() => document.querySelector('#serverStatus').dataset.kind === 'ok');
  assert.ok(await options.locator('#serverModels option').evaluateAll((els, model) => els.some(e => e.value === model), model));
  await options.locator('#testEngine').click();
  await options.waitForFunction(() => ['ok', 'error'].includes(document.querySelector('#testStatus').dataset.kind), null, { timeout: 180000 });
  assert.equal(await options.locator('#testStatus').getAttribute('data-kind'), 'ok', await options.locator('#testStatus').innerText());
  await record('actual-server-model-list-and-unsaved-keyless-translation-test', { requests: records.length });
  requireAuth = true;
  await options.locator('#serverApiKey').fill('deliberately-wrong-test-key');
  await options.locator('#testEngine').click();
  await options.waitForFunction(() => document.querySelector('#testStatus').dataset.kind === 'error');
  assert.match(await options.locator('#testStatus').innerText(), /401/);
  await options.locator('#serverApiKey').fill(credential);
  await options.locator('#testEngine').click();
  await options.waitForFunction(() => ['ok', 'error'].includes(document.querySelector('#testStatus').dataset.kind), null, { timeout: 180000 });
  assert.equal(await options.locator('#testStatus').getAttribute('data-kind'), 'ok');
  await options.locator('#save').click();
  await options.waitForFunction(() => document.querySelector('#saveStatus').dataset.kind === 'ok');
  await screenshot(options, 'server-options-configured');
  await record('bearer-auth-error-and-real-authenticated-translation');
  const page = await context.newPage(); await page.goto('http://127.0.0.1:' + fixture.address().port + '/page');
  const other = await context.newPage(); await other.goto('http://127.0.0.1:' + fixture.address().port + '/other');
  const state = await options.evaluate(async url => {
    const tab = (await AT.api.tabs.query({})).find(t => t.url === url);
    return { tabId: tab.id, state: await AT.sendMessage({ type: AT.C.MSG.GET_STATE, tabId: tab.id }) };
  }, page.url());
  assert.equal(state.state.tabEnabled, false);
  await options.goto(root + '/options.html?tabId=' + state.tabId);
  await options.waitForFunction(() => document.body.dataset.ready === 'true' && !document.querySelector('#enabled').disabled);
  const original = await page.locator('body').innerHTML();
  const element = await page.locator('#hello').elementHandle();
  await options.locator('#enabled').check();
  const started = performance.now();
  await page.waitForFunction(() => ['#hello','#thanks','#inline a'].every(s => /[가-힣]/u.test(document.querySelector(s).textContent)), null, { timeout: 180000 });
  assert.equal(await other.locator('#hello').innerText(), 'Hello.');
  assert.equal(await page.locator('#inline a').getAttribute('href'), '/guide');
  await screenshot(page, 'server-page-translated');
  await options.locator('#enabled').uncheck();
  await page.waitForFunction(html => document.body.innerHTML === html, original);
  assert.equal(await element.evaluate(e => e === document.querySelector('#hello')), true);
  await record('real-server-tab-opt-in-translation-and-exact-html-restoration', { elapsedMs: performance.now() - started, otherTabUnchanged: true });
  await writeFile(join(out, 'original.html'), original);
  await writeFile(join(out, 'restored.html'), await page.locator('body').innerHTML());
  await options.locator('#enabled').check();
  await page.waitForFunction(() => /[가-힣]/u.test(document.querySelector('#hello').textContent), null, { timeout: 180000 });
  await page.evaluate(() => { const p = document.createElement('p'); p.id = 'added'; p.textContent = 'Good morning.'; document.querySelector('#late').append(p); });
  await page.waitForFunction(() => /[가-힣]/u.test(document.querySelector('#added').textContent), null, { timeout: 180000 });
  await page.evaluate(() => document.querySelector('#added').firstChild.nodeValue = 'See you tomorrow.');
  await page.waitForFunction(() => /[가-힣]/u.test(document.querySelector('#added').textContent), null, { timeout: 180000 });
  await screenshot(page, 'server-dynamic-translated');
  await options.locator('#enabled').uncheck();
  await page.waitForFunction(() => document.querySelector('#hello').textContent === 'Hello.' && document.querySelector('#added').textContent === 'See you tomorrow.');
  assert.equal(await page.locator('#draft').inputValue(), 'private draft');
  await page.locator('#click').click(); assert.equal(await page.evaluate(() => window.clicks), 1);
  await record('dynamic-insertion-text-node-reuse-and-current-source-restore');
  const count = records.length;
  await page.evaluate(() => document.querySelector('#added').textContent = 'Good night.');
  await other.bringToFront(); await sleep(1200);
  assert.equal(records.length, count, 'unselected and disabled tabs must not generate requests');
  const snapshot = await options.evaluate(async () => AT.settings.contentSnapshot(await AT.settings.load()));
  assert.equal(JSON.stringify(snapshot).includes(credential), false);
  const localState = await options.evaluate(async () => {
    const s = await AT.settings.load();
    const contexts = await chrome.runtime.getContexts({ contextTypes: ['OFFSCREEN_DOCUMENT'] });
    const host = await AT.sendMessage({ type: AT.C.MSG.LOCAL_GET_STATUS });
    return { engine: s.engine, localModelId: s.localModelId, offscreenCount: contexts.length, loadedBytes: host.status?.loadedBytes ?? 0, generations: host.status?.generations ?? 0 };
  });
  assert.equal(localState.engine, 'openai');
  assert.equal(localState.localModelId, '');
  assert.equal(localState.loadedBytes, 0);
  assert.equal(localState.generations, 0);
  const isolation = await options.evaluate(async id => (await chrome.scripting.executeScript({target:{tabId:id}, func:async()=> {
    try { const s=await chrome.storage.local.get('settings'); return !!s.settings?.serverApiKey; } catch { return false; }
  }}))[0].result, state.tabId);
  assert.equal(isolation, false, 'API key must not be readable from content-script storage');
  assert.equal(records.some(r => r.credentialsInBody), false);
  await record('server-mode-needs-no-local-model-or-native-generation-and-keeps-key-out-of-content', localState);
  forcedStatus = 429;
  await options.locator('#enabled').check();
  await options.waitForFunction(async tabId => {
    const state=await AT.sendMessage({type:AT.C.MSG.GET_STATE,tabId}); return state.state?.status==='error';
  }, state.tabId, {timeout:30000});
  assert.equal(await page.locator('#hello').innerText(), 'Hello.');
  await options.locator('#enabled').uncheck(); forcedStatus = null;
  await options.locator('#enabled').check();
  await page.waitForFunction(() => /[가-힣]/u.test(document.querySelector('#hello').textContent), null, { timeout: 180000 });
  await options.locator('#enabled').uncheck();
  await page.waitForFunction(() => document.querySelector('#hello').textContent === 'Hello.');
  await record('HTTP-rate-limit-fails-without-DOM-corruption-and-explicit-retry-recovers');
  await screenshot(page, 'server-final-restored');
  summary.requests = records;
  summary.installedFilesUnchanged = JSON.stringify(before) === JSON.stringify(await hashes(extension));
  assert.equal(summary.installedFilesUnchanged, true);
  assert.deepEqual(summary.errors, []);
  summary.passed = true;
} catch (error) {
  summary.failure = { message: clean(error.message), stack: clean(error.stack) };
  summary.requests = records;
  if (context) for (const [index, p] of context.pages().entries()) await screenshot(p, 'FAIL-' + index).catch(() => {});
  throw error;
} finally {
  await writeFile(join(out, 'summary.json'), JSON.stringify(summary, null, 2));
  await writeFile(join(out, 'installed-sha256.json'), JSON.stringify(before, null, 2));
  await context?.close(); await close(fixture); await close(gateway);
  if (profile) await rm(profile, { recursive: true, force: true });
}
